CREATE POLICY "Fan avatars are readable" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'fan-avatars');
CREATE POLICY "Fans upload their avatar" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'fan-avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Fans update their avatar" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'fan-avatars' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'fan-avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Fans delete their avatar" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'fan-avatars' AND (storage.foldername(name))[1] = auth.uid()::text);